import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
from collections import Counter
for k,v in G.items():
    print(k, Counter(x for r in v for x in r))

def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    # background = most common
    from collections import Counter
    c=Counter(x for r in g for x in r); bg=c.most_common(1)[0][0]
    seeds=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg: seeds.append((i,j,g[i][j]))
    out=[r[:] for r in g]
    for i,j,val in seeds:
        k=j+1
        while k<W:
            out[i][k]=5
            k+=1
        k=j+2
        while k<W:
            out[i][k]=val
            k+=2
    return out
for n in (1,2):
    a=f(G[f'Demo pair {n} input']); b=G[f'Demo pair {n} output']
    print(n, a==b)
    if a!=b:
        for r in range(len(a)):
            if a[r]!=b[r]: print(r,a[r],b[r])
print(json.dumps(f(G['Test input'])))
